  top.Background=fullscreen?Brushes.Black:Brushes.Transparent;top.Opacity=fullscreen?1:Math.Max(.3,Math.Min(1,cfg.TopOpacity));
  if(reserve){if(!topReserved){var add=new Native.APPBAR{Size=Marshal.SizeOf(typeof(Native.APPBAR)),Hwnd=new System.Windows.Interop.WindowInteropHelper(top).Handle,Callback=topAppBarCallback,Edge=1};topReserved=Native.SHAppBarMessage(0,ref add)!=UIntPtr.Zero;}if(topReserved&&topReservedHeight!=physicalHeight){var bar=new Native.APPBAR{Size=Marshal.SizeOf(typeof(Native.APPBAR)),Hwnd=new System.Windows.Interop.WindowInteropHelper(top).Handle,Callback=topAppBarCallback,Edge=1,Rect=new Native.RECT{Left=0,Top=0,Right=System.Windows.Forms.Screen.PrimaryScreen.Bounds.Width,Bottom=physicalHeight}};Native.SHAppBarMessage(2,ref bar);bar.Rect.Bottom=bar.Rect.Top+physicalHeight;Native.SHAppBarMessage(3,ref bar);topReservedHeight=physicalHeight;}}
