 FrameworkElement BatteryToolbarPanel(){var power=System.Windows.Forms.SystemInformation.PowerStatus;double percent=Math.Max(0,Math.Min(100,power.BatteryLifePercent*100));var row=new Grid{Width=360,Height=54};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(62)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(66)});var icon=Action("",()=>Launch("ms-settings:batterysaver"));icon.Content=NavIcon("Battery",accentBrush,27,2.2);icon.Padding=new Thickness(0);icon.Margin=new Thickness(0,0,16,0);row.Children.Add(icon);var bar=new ProgressBar{Minimum=0,Maximum=100,Value=percent,Height=8,Foreground=accentBrush,Background=cardBrush,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(bar,1);row.Children.Add(bar);var value=Text(Math.Round(percent)+"%",18);value.FontWeight=FontWeights.SemiBold;value.TextAlignment=TextAlignment.Right;Grid.SetColumn(value,2);row.Children.Add(value);return row;}
 int ReadBrightness(){try{using(var query=new ManagementObjectSearcher("root\\WMI","SELECT CurrentBrightness FROM WmiMonitorBrightness"))foreach(ManagementObject value in query.Get())return Convert.ToInt32(value["CurrentBrightness"]);}catch(Exception error){Log("Brightness: "+error.Message);}return -1;}
