 FrameworkElement BrightnessToolbarPanel(){int level=ReadBrightness();var row=new Grid{Width=360,Height=54};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(54)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(58)});var icon=NavIcon("Brightness",accentBrush,26,2);icon.HorizontalAlignment=HorizontalAlignment.Center;row.Children.Add(icon);if(level<0){var unavailable=Text("Brightness is controlled by this display",12,mutedBrush);Grid.SetColumn(unavailable,1);Grid.SetColumnSpan(unavailable,2);row.Children.Add(unavailable);return row;}var slider=new Slider{Minimum=0,Maximum=100,Value=level,VerticalAlignment=VerticalAlignment.Center,Foreground=accentBrush};StyleSlider(slider);var value=Text(level+"%",16);value.TextAlignment=TextAlignment.Right;slider.AddHandler(Thumb.DragCompletedEvent,new DragCompletedEventHandler(delegate{WriteBrightness((int)slider.Value);}));slider.PreviewMouseLeftButtonUp+=delegate{WriteBrightness((int)slider.Value);};slider.ValueChanged+=delegate{value.Text=Math.Round(slider.Value)+"%";};Grid.SetColumn(slider,1);Grid.SetColumn(value,2);row.Children.Add(slider);row.Children.Add(value);return row;}
