 FrameworkElement StandardToolbarPanel(string kind){if(kind=="Volume"||kind=="Microphone")return AudioToolbarPanel(kind);if(kind=="Battery")return BatteryToolbarPanel();if(kind=="Brightness")return BrightnessToolbarPanel();if(kind=="Wi-Fi")return CompactWifiPanel();var content=new StackPanel{Width=360};var title=Text(kind,18);title.FontWeight=FontWeights.SemiBold;content.Children.Add(title);var note=Text("",12,mutedBrush);note.Margin=new Thickness(0,10,0,8);content.Children.Add(note);if(kind=="Wi-Fi")WifiPanel(content,note);else if(kind=="Bluetooth"){note.Text=bluetooth.Text;content.Children.Add(Switch("Bluetooth",bluetooth.Text.Contains("on"),v=>{try{var ignored=SetBluetooth(v);}catch{}}));content.Children.Add(Action("Open Bluetooth settings",()=>Launch("ms-settings:bluetooth")));}return content;}
 async System.Threading.Tasks.Task SetBluetooth(bool enabled){try{var radios=await System.WindowsRuntimeSystemExtensions.AsTask<IReadOnlyList<global::Windows.Devices.Radios.Radio>>(global::Windows.Devices.Radios.Radio.GetRadiosAsync());var radio=radios.FirstOrDefault(x=>x.Kind==global::Windows.Devices.Radios.RadioKind.Bluetooth);if(radio!=null)await System.WindowsRuntimeSystemExtensions.AsTask<global::Windows.Devices.Radios.RadioAccessStatus>(radio.SetStateAsync(enabled?global::Windows.Devices.Radios.RadioState.On:global::Windows.Devices.Radios.RadioState.Off));}catch(Exception error){Log("Bluetooth: "+error.Message);}}

