 void NotificationPanel(StackPanel host){
  var header=new DockPanel();var clear=Action("Clear all",()=>{try{UserNotificationListener.Current.ClearNotifications();}catch{}if(systemPopup!=null)systemPopup.IsOpen=false;});clear.Foreground=accentBrush;DockPanel.SetDock(clear,Dock.Right);header.Children.Add(clear);var title=Text("Notifications",22);title.FontWeight=FontWeights.SemiBold;header.Children.Add(title);host.Children.Add(header);var list=new StackPanel{Margin=new Thickness(0,12,0,0)};list.Children.Add(Text("Loading notifications…",12,mutedBrush));host.Children.Add(new ScrollViewer{Content=list,MaxHeight=400,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden});host.Children.Add(NotificationQuickSettings());var ignored=LoadNotifications(list);
