 async System.Threading.Tasks.Task LoadNotifications(StackPanel list){
  try{var listener=UserNotificationListener.Current;var access=await System.WindowsRuntimeSystemExtensions.AsTask<UserNotificationListenerAccessStatus>(listener.RequestAccessAsync());if(access!=UserNotificationListenerAccessStatus.Allowed)throw new InvalidOperationException("Notification access is unavailable.");var notices=await System.WindowsRuntimeSystemExtensions.AsTask<IReadOnlyList<UserNotification>>(listener.GetNotificationsAsync(NotificationKinds.Toast));list.Children.Clear();var values=notices.OrderByDescending(x=>x.CreationTime).ToList();foreach(var period in new[]{"Today","Earlier"}){var periodItems=values.Where(x=>(x.CreationTime.LocalDateTime.Date==DateTime.Today)==(period=="Today")).ToList();if(periodItems.Count==0)continue;var heading=Text(period,14,mutedBrush);heading.Margin=new Thickness(2,8,0,8);list.Children.Add(heading);foreach(var group in periodItems.GroupBy(NotificationAppName)){list.Children.Add(NotificationGroup(group.Key,group.ToList()));}}if(values.Count==0)list.Children.Add(Text("No notifications",13,mutedBrush));}
  catch(Exception error){list.Children.Clear();list.Children.Add(Text("Windows notification history is unavailable",13));var detail=Text(error.Message,11,mutedBrush);detail.Margin=new Thickness(0,7,0,0);list.Children.Add(detail);}
 }
 string NotificationAppName(UserNotification notice){try{return notice.AppInfo.DisplayInfo.DisplayName;}catch{return "Windows";}}
 string[] NotificationText(UserNotification notice){try{var binding=notice.Notification.Visual.GetBinding(KnownNotificationBindings.ToastGeneric);return binding==null?new string[0]:binding.GetTextElements().Select(x=>x.Text).Where(x=>!String.IsNullOrWhiteSpace(x)).ToArray();}catch{return new string[0];}}
 FrameworkElement NotificationGroup(string app,List<UserNotification> notices){var stack=new StackPanel();var top=new DockPanel();var appName=Text(app,16);appName.FontWeight=FontWeights.SemiBold;top.Children.Add(appName);stack.Children.Add(top);foreach(var notice in notices){var texts=NotificationText(notice);var row=new DockPanel{Margin=new Thickness(0,7,0,3)};var time=Text(RelativeTime(notice.CreationTime.LocalDateTime),11,mutedBrush);DockPanel.SetDock(time,Dock.Right);row.Children.Add(time);var message=Text(texts.Length==0?"Notification":String.Join("\n",texts.Take(3)),13);row.Children.Add(message);stack.Children.Add(row);string combined=app+" "+String.Join(" ",texts);if(combined.IndexOf("update",StringComparison.OrdinalIgnoreCase)>=0){var action=Action("Review update",()=>{if(systemPopup!=null)systemPopup.IsOpen=false;if(app.IndexOf("Awl",StringComparison.OrdinalIgnoreCase)>=0){activeTab="Config";if(launcher==null||!launcher.IsVisible)ToggleLauncher();else DrawLauncher();}else Launch("ms-settings:windowsupdate");});action.HorizontalAlignment=HorizontalAlignment.Left;stack.Children.Add(action);}}return new Border{Background=cardBrush,CornerRadius=new CornerRadius(17),Padding=new Thickness(16),Margin=new Thickness(0,0,0,10),Child=stack};}
