 List<Tuple<IntPtr,string,string>> AltTabCandidates(){var values=new List<Tuple<IntPtr,string,string>>();Native.EnumWindows(delegate(IntPtr h,IntPtr unused){if(!Native.IsWindowVisible(h)||(Native.GetWindowLong(h,-20)&0x80)!=0)return true;int cloaked;Native.DwmGetWindowAttribute(h,14,out cloaked,4);if(cloaked!=0)return true;uint pid;Native.GetWindowThreadProcessId(h,out pid);if(pid==selfPid)return true;var text=new StringBuilder(512);Native.GetWindowText(h,text,512);if(text.Length==0||text.ToString()=="Program Manager")return true;string path="";try{using(var process=Process.GetProcessById((int)pid))path=process.MainModule.FileName;}catch{}values.Add(Tuple.Create(h,text.ToString(),path));return true;},IntPtr.Zero);return values;}
 ImageSource CaptureWindowPreview(IntPtr hwnd){Native.RECT rect;if(!Native.GetWindowRect(hwnd,out rect))return null;int width=Math.Max(1,Math.Min(3840,rect.Right-rect.Left)),height=Math.Max(1,Math.Min(2160,rect.Bottom-rect.Top));if(width<2||height<2)return null;try{using(var bitmap=new System.Drawing.Bitmap(width,height,System.Drawing.Imaging.PixelFormat.Format32bppArgb))using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){IntPtr hdc=graphics.GetHdc();bool drawn=false;try{drawn=Native.PrintWindow(hwnd,hdc,2);}finally{graphics.ReleaseHdc(hdc);}if(!drawn)return null;IntPtr handle=bitmap.GetHbitmap();try{var image=Imaging.CreateBitmapSourceFromHBitmap(handle,IntPtr.Zero,Int32Rect.Empty,BitmapSizeOptions.FromEmptyOptions());image.Freeze();return image;}finally{DeleteObject(handle);}}}catch(Exception error){Log("Window preview: "+error.Message);return null;}}
 void ShowAltTab(bool reverse){if(altTabWindow==null||!altTabWindow.IsVisible){altTabItems=AltTabCandidates();altTabPreviews.Clear();if(altTabItems.Count==0)return;altTabIndex=altTabItems.Count==1?0:reverse?altTabItems.Count-1:1;if(altTabWindow!=null)altTabWindow.Close();altTabWindow=new Window{Title="Awl switcher",WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,ShowActivated=false,Topmost=true,Width=Math.Min(1100,40+Math.Min(5,altTabItems.Count)*216),Height=230,WindowStartupLocation=WindowStartupLocation.CenterScreen};altTabWindow.Closed+=delegate{altTabShowing=false;altTabWindow=null;};altTabShowing=true;DrawAltTab();altTabWindow.Show();}else{altTabIndex=(altTabIndex+(reverse?-1:1)+altTabItems.Count)%altTabItems.Count;DrawAltTab();}}
 void DrawAltTab(){if(altTabWindow==null)return;var row=new StackPanel{Orientation=Orientation.Horizontal};int pageStart=(altTabIndex/5)*5;for(int i=0;i<5;i++){int index=pageStart+i;if(index>=altTabItems.Count)break;var item=altTabItems[index];var tile=new StackPanel{Width=198,Margin=new Thickness(5),Cursor=System.Windows.Input.Cursors.Hand};var preview=new Border{Height=140,CornerRadius=new CornerRadius(18),Background=cardBrush,BorderBrush=index==altTabIndex?accentBrush:new SolidColorBrush(Color.FromArgb(50,255,255,255)),BorderThickness=new Thickness(index==altTabIndex?3:1),ClipToBounds=true};var frame=new Grid();ImageSource capture;if(!altTabPreviews.TryGetValue(item.Item1,out capture)){capture=CaptureWindowPreview(item.Item1);altTabPreviews[item.Item1]=capture;}if(capture!=null)frame.Children.Add(new Image{Source=capture,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center});var icon=AppIcon(item.Item3);if(icon!=null){var badge=new Border{Background=new SolidColorBrush(Color.FromArgb(205,20,28,27)),CornerRadius=new CornerRadius(8),Padding=new Thickness(6),Margin=new Thickness(8),HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Bottom,Child=new Image{Source=Tone(icon),Width=28,Height=28}};frame.Children.Add(badge);}preview.Child=frame;tile.Children.Add(preview);var name=Text(item.Item2,13);name.FontWeight=FontWeights.SemiBold;name.TextAlignment=TextAlignment.Center;name.TextTrimming=TextTrimming.CharacterEllipsis;name.TextWrapping=TextWrapping.NoWrap;name.Margin=new Thickness(4,8,4,0);tile.Children.Add(name);int chosen=index;tile.MouseLeftButtonUp+=delegate{altTabIndex=chosen;FinishAltTab(true);};row.Children.Add(tile);}altTabWindow.Content=PopupSurface(row,24);}
 void FinishAltTab(bool activate){var window=altTabWindow;if(window==null)return;var selected=altTabItems.Count>altTabIndex&&altTabIndex>=0?altTabItems[altTabIndex]:null;altTabShowing=false;altTabWindow=null;try{window.Close();}catch{}if(activate&&selected!=null)Dispatcher.BeginInvoke(DispatcherPriority.Input,new Action(delegate{if(Native.IsIconic(selected.Item1))Native.ShowWindowAsync(selected.Item1,9);Native.ShowWindowAsync(selected.Item1,5);Native.SetForegroundWindow(selected.Item1);}));}
